def roman(n):
    if not 1 <= n <= 3999:
        raise ValueError("n must be between 1 and 3999")
    pairs = [
        (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
        (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
        (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
    ]
    result = []
    for value, symbol in pairs:
        while n >= value:
            result.append(symbol)
            n -= value
    return "".join(result)
```

