def diff_lines(a, b):
    result = []
    for i in range(max(len(a), len(b))):
        if i < len(a) and i < len(b):
            if a[i] == b[i]:
                result.append((' ', a[i]))
            else:
                result.append(('-', a[i]))
                result.append(('+', b[i]))
        elif i < len(a):
            result.append(('-', a[i]))
        else:
            result.append(('+', b[i]))
    return result
